<?php
declare(strict_types=1); namespace PWT\Staff\CRM; defined('ABSPATH')||exit;
final class FollowUpRepository { public const POST_TYPE='pwt_customer_followup'; public function register():void{register_post_type(self::POST_TYPE,['label'=>'Customer Follow-ups','public'=>false,'show_ui'=>false,'supports'=>['title']]);} public function create(array $d):int{$id=wp_insert_post(['post_type'=>self::POST_TYPE,'post_status'=>'publish','post_title'=>sanitize_text_field($d['title']??'Customer Follow-up')]);if(is_wp_error($id))return 0;foreach(['customer_id','booking_id','assigned_user_id','follow_up_date','type','priority','status','notes'] as $k)update_post_meta($id,'_pwt_followup_'.$k,$d[$k]??'');return(int)$id;} public function due():array{return get_posts(['post_type'=>self::POST_TYPE,'numberposts'=>-1,'meta_query'=>[['key'=>'_pwt_followup_status','value'=>'completed','compare'=>'!=']]]);} }
